update_invalid=[]
for u in updates:
 p=u['outcomes']
 if u['question_id'] not in active or len(p)>5 or sum(p.values())>1.000000001:
  update_invalid.append((u['question_id'],len(p),sum(p.values())))
print({'active':len(active),'covered':len(active)-len(missing),'missing':missing,'existing_invalid':invalid,'updates':len(updates),'update_invalid':update_invalid,'new_resolutions':len(resolutions)})
PY"

